from typing import Dict, Any

def get_cung_dau_duoc_y_thuc_tinh_masterpiece_story(title: str = '') -> Dict[str, Any]:
    story_title = title if title else "Thứ Nữ Ngự Y: Một Nén Hương Thử Độc San Bằng Thâm Cung"
    part1_full = "Mùi trầm hương pha lẫn vị hạnh nhân đắng nồng nặc bốc lên từ chiếc chén ngọc bích vỡ nát dưới chân giường tẩm điện, nơi Tiêu Quý phi đang nằm thoi thóp giữa đêm khuya. Vừa bước chân vào tẩm điện ngập tràn mùi trầm hương lúc nửa đêm, tôi đã nghe thấy tiếng gốm sứ vỡ tan tành dưới chân.\n\nTrước mặt tôi, Tiêu Quý phi đang tựa lưng vào chiếc gối gấm thêu phượng hoàng, đôi mắt sắc lạnh như dao liếc nhìn xuống sàn nhà. Dưới đất là một chén thuốc an thai mạ vàng còn bốc khói nghi ngút, nước thuốc đen sánh chảy lênh láng trên tấm thảm dệt hoa văn hoa cúc trắng tinh xảo.\n\nMẹ kế của tôi, phu nhân họ Liễu của Chu gia, lập tức đẩy mạnh tôi về phía trước. Bà ta nghiến răng thì thầm qua kẽ môi, giọng nói vừa run rẩy vừa độc địa: \"Con ranh vô dụng, còn không mau quỳ xuống bắt mạch cho Quý phi? Hôm nay nếu Quý phi và long thai trong bụng có mệnh hệ nào, cả phủ họ Chu của ngươi đừng hòng có một người sống sót bước ra khỏi cửa thành!\"\n\nTôi không đáp lời, chỉ lẳng lặng quỳ một gối xuống sàn đá hoa cương lạnh buốt như băng. Bàn tay tôi đặt chiếc hộp thuốc bằng gỗ đàn hương cũ kỹ xuống đất, nhẹ nhàng mở ra ba tầng ngăn kéo nhỏ bên trong.\n\nTôi là Chu Diệp Anh, thứ nữ sinh ra từ một người thiếp làm nghề bốc thuốc ở thảo nguyên hoang sơ phía bắc. Mười năm qua, tôi bị nhốt dưới căn nhà kho ẩm mốc ở hậu viện Chu gia, ngày ngày giã thuốc, nếm từng ngọn cỏ và thuộc làu từng trang cổ thư y thuật bí truyền của mẫu thân để lại. Đến khi Tiêu Quý phi trong cung có dấu hiệu sẩy thai bí ẩn, ba vị đại phu danh tiếng lẫy lừng của Thái Y Viện đều lắc đầu bất lực và chịu giam lỏng, Chu gia mới cuống cuồng lôi tôi ra khỏi góc tối, khoác lên người tôi bộ y phục cung tỳ mộc mạc để đưa vào cung làm kẻ chịu tội thay cho đại cục.\n\n\"Ngẩng mặt lên.\" Giọng nói của Tiêu Quý phi vang lên từ sau tấm rèm ngọc rủ xuống, lạnh tanh không chút hơi ấm của tình người. \"Nghe đồn ngươi nếm qua một ngụm trà là biết trong đó có bao nhiêu vị thuốc độc? Bắt mạch cho bản cung đi. Nếu ngươi dám nói một lời dối trá, sáng mai đầu của cha ngươi và mẹ kế ngươi sẽ được treo trước cổng thành cho thiên hạ cùng ngắm nhìn.\"\n\nTôi bước tới gần mép giường gấm, khẽ cúi đầu xin phép rồi đặt đầu ngón tay thanh mảnh lên cổ tay trắng nõn của Quý phi.\n\nMạch tượng nhảy loạn xạ, trầm mà sáp, bên ngoài có vẻ suy nhược do hàn khí xâm nhập nhưng bên trong lại có một luồng nhiệt độc dữ dội đang âm thầm gặm nhấm kinh mạch và tử cung. Nhưng điều khiến sống lưng tôi lạnh toát không phải là mạch tượng phức tạp ấy, mà chính là mùi hương thoang thoảng phát ra từ chiếc lò xông trầm hình chim loan bằng đồng đang đặt ở đầu giường ngủ.\n\nMùi trầm hương này rất đậm, nồng nàn đến mức khiến bất kỳ ai bước vào phòng cũng phải choáng váng nghẹt thở. Nhưng ẩn sâu dưới lớp khói trắng mờ ảo bốc lên từ lò đồng ấy là một mùi hương ngọt lịm đến gai người, mùi của xạ hương tuyết liên kết hợp với phấn hoa linh lan trắng phơi khô. Hai vị này nếu dùng riêng lẻ thì là thuốc bổ khí huyết cực kỳ quý giá, nhưng khi hòa trộn cùng nhau trong một không gian kín gió suốt đêm dài, nó sẽ biến thành một loại kịch độc vô hình, khiến thai phụ trụy thai trong vòng ba mươi ngày mà không để lại bất kỳ dấu vết nào trên phủ tạng hay da thịt.\n\nTôi khẽ rút ngón tay về, thu lại đầu kim bạc nhỏ xíu vốn giấu kín trong kẽ móng tay trỏ.\n\nDưới ánh nến lung linh mờ ảo, đầu kim bạc vốn sáng lấp lánh như sương mai lúc này đã biến thành một màu tím sẫm ma mị đến rợn người.\n\n\"Bẩm Quý phi nương nương,\" tôi ngước mắt lên, ánh nhìn thẳng thắn, trong trẻo và bình thản đến mức Tiêu Quý phi phải khựng lại một nhịp thở, \"long mạch của người vẫn bình an, thai nhi vẫn còn cơ hội cứu vãn, nhưng tẩm điện này thì sắp có một vụ án mạng chấn động hoàng tộc.\"\n\nPhu nhân họ Liễu đứng phía sau sợ đến mức hai đầu gối run lẩy bẩy, mặt cắt không còn một giọt máu. Bà ta vội vàng lao tới túm chặt lấy bả vai tôi, gắt lên the thé: \"Con súc sinh này! Ngươi ăn nói xằng bậy gì trước mặt Quý phi thế hả? Người đâu, vả miệng con nha đầu điên khùng này cho ta, đừng để nó làm ô uế tẩm điện của nương nương!\"\n\n\"Để nó nói tiếp.\" Tiêu Quý phi giơ bàn tay thon dài đeo chiếc hộ giáp bằng vàng ròng nạm ngọc bích lên, giọng bà ta trầm xuống đầy nguy hiểm và sát khí. \"Ngươi vừa bảo tẩm điện này có án mạng? Ai muốn hại bản cung? Là ai to gan lớn mật đến mức dám động vào giọt máu rồng trong bụng ta?\"\n\nTôi không hề liếc nhìn người mẹ kế đang run rẩy, chỉ đưa tay chỉ thẳng vào chiếc lò xông trầm bằng đồng đang nghi ngút khói ở góc phòng: \"Nếu Quý phi không tin lời tiện tỳ, xin hãy cho hạ lệnh dập tắt chiếc lò hương đó ngay lập tức. Sau đó, cho người mang vào đây một chậu than hoa sạch không khói và một chén giấm trắng nóng còn đang sôi trên bếp.\"\n\nÁnh mắt Tiêu Quý phi nheo lại thật chặt, bà ta nhìn tôi chằm chằm suốt mấy giây dài đằng đẵng như muốn xé toạc tâm can tôi để tìm ra sự dối trá. Cuối cùng, bà ta khẽ phất tay áo rộng: \"Làm theo lời nó nói. Nếu lát nữa ngươi không chứng minh được lời mình vừa thốt ra, bản cung sẽ cho người đổ nguyên cả lò than hoa đang cháy rực vào họng ngươi để ngươi vĩnh viễn không thể cất lời nói bậy.\"\n\nThái giám thân cận lập tức mang một thau than hoa và một chén giấm nóng nghi ngút khói vào phòng.\n\nTrước sự chứng kiến đầy căng thẳng của toàn bộ cung nữ, thái giám và mẹ kế tôi, tôi bước tới chiếc lò hương bằng đồng, dùng chiếc kẹp bạc cẩn thận gắp ra một nắm bột trầm chưa cháy hết rồi thả thẳng vào chén giấm nóng.\n\nMột làn khói màu tím sẫm lập tức bốc lên xộc thẳng vào mũi mọi người, kèm theo tiếng xèo xèo tanh nồng như mùi máu tươi rỉ sét. Giọt giấm trắng trong veo trong chớp mắt biến thành màu đen kịt như mực tàu, nổi lên những váng bọt nhờn nhớt bốc mùi cay sè.\n\nCả tẩm điện rộng lớn rơi vào một sự im lặng chết chóc đến mức nghe rõ cả tiếng tim đập dồn dập.\n\nSắc mặt của Tiêu Quý phi từ vẻ kiêu ngạo thường ngày chuyển dần sang trắng bệch, rồi sau đó là một cơn phẫn nộ tột cùng khiến bàn tay bà ta run rẩy dữ dội. Chiếc lò hương quý báu này là cống phẩm thượng hạng do chính tay Hoàng hậu nương nương ban tặng cho bà ta vào ngày bà ta đón nhận tin vui mang thai tháng thứ ba!\n\n\"Hoàng... Hoàng hậu sao?\" Tiêu Quý phi lẩm bẩm, giọng nghẹn lại trong cổ họng đầy cay đắng.\n\n\"Không phải Hoàng hậu nương nương.\" Tôi lạnh lùng lên tiếng, dứt khoát ngắt lời suy đoán đầy thiên kiến của bà ta. \"Hoàng hậu nương nương xuất thân từ gia đình võ tướng ba đời gìn giữ biên cương, tính tình cương trực quang minh lỗi lạc, nếu muốn triệt hạ ai sẽ dùng gươm giáo trên chiến trường chứ không bao giờ thèm dùng thứ mưu hèn kế bẩn này. Hương liệu này tuy mang vỏ bọc cống phẩm của Phượng Nghi Cung, nhưng loại keo dính kết bột trầm bên trong lại là keo thông mật đặc sản chỉ có ở vùng Giang Nam, nơi mà phủ bá tước của mẫu tộc Thục Phi nương nương đang cai quản và thu mua hàng năm.\"\n\nTiêu Quý phi siết chặt chiếc hộ giáp nạm ngọc, cắm ngập vào lòng bàn tay mềm mại đến mức bật ra những giọt máu tươi đỏ thắm. Bà ta nhìn tôi bằng ánh mắt hoàn toàn thay đổi, không còn là sự khinh thường một con a hoàn hèn mọn, mà là nỗi kinh ngạc và sợ hãi trước một kẻ nắm giữ bí mật sinh tử của cả sáu cung.\n\n\"Ngươi rốt cuộc là ai?\" Quý phi thở dốc hỏi, ánh mắt lóe lên tia sáng hy vọng mong manh.\n\n\"Tôi chỉ là một đứa thứ nữ hèn mọn bị ruồng bỏ của Chu gia.\" Tôi dập đầu sát đất, từng lời thốt ra đanh thép như đinh đóng cột: \"Nhưng nếu nương nương muốn giữ lại đứa con này bình an chào đời, và muốn vạch mặt kẻ đang muốn đẩy người xuống vực sâu vạn trượng, nương nương chỉ có thể tin tưởng một mình tôi.\"\n\nTiêu Quý phi nhìn tôi thật lâu giữa làn khói trầm mỏng manh, rồi chậm rãi nở một nụ cười lạnh buốt: \"Được lắm. Từ đêm nay, ngươi là ngự y riêng phụ trách ăn uống và thuốc thang của cung Vĩnh Hòa. Nhưng ngươi hãy nhớ kỹ lời bản cung, ở chốn hoàng cung sâu thẳm này, mạng sống của ngươi chỉ đáng giá bằng một nén nhang thử độc mà thôi. Nếu nhang tàn mà ngươi thất bại, ngươi sẽ là kẻ chết đầu tiên!\""
    part2_full = "Hồi chuông đồng từ điện Càn Thanh vừa gióng lên báo hiệu giờ thiết triều sáng sớm, toàn bộ thái y viện đã bị cấm quân vây chặt không một kẽ hở. Ba ngày sau khi tôi chính thức bước chân vào cung Vĩnh Hòa, cơn sóng ngầm thật sự mới bắt đầu bùng nổ khắp hoàng thành.\n\nSáng sớm hôm đó, tiếng chuông đồng từ Cung Càn Thanh vang lên dồn dập từng hồi báo hiệu giờ thiết triều buổi sớm đã kết thúc. Chưa đầy nửa khắc sau, một đoàn thị vệ cấm quân mặc giáp sắt sáng loáng do Thống lĩnh Tiết Vũ chỉ huy đã bao vây chặt chẽ toàn bộ cửa viện của cung Vĩnh Hòa. Đi cùng đoàn người hùng hậu ấy là Ôn Thuận Cảnh, vị chưởng quản quyền lực nhất của Thái Y Viện suốt hai mươi năm qua, và Thục Phi, người đang khoác trên mình chiếc áo choàng gấm thêu hoa trà đỏ rực rỡ lộng lẫy.\n\nThục Phi vừa bước qua ngạch cửa tẩm điện đã rút chiếc khăn tay viền đăng ten chấm khóe mắt, cất giọng nghẹn ngào ai oán: \"Quý phi tỷ tỷ ơi, muội muội nghe tin tỷ tỷ mấy ngày nay không chịu dùng thuốc an thai của Thái Y Viện, lại để một con a hoàn xuất thân lang băm ngoài chợ đen bốc thuốc dâng trà. Chuyện này chẳng may đã truyền đến tai Hoàng thượng, người lo lắng cho long thể của tỷ tỷ đến mất ăn mất ngủ nên mới phái Ôn chưởng viện và cấm quân đến đây đích thân kiểm tra sự tình.\"\n\nTiêu Quý phi ngồi ngay ngắn trên chiếc sập gụ khảm ốc xà cừ, sắc mặt tuy vẫn còn xanh xao vì dư độc trong người nhưng phong thái vẫn ngút ngàn sự kiêu hãnh của một sủng phi: \"Muội muội thật là nhọc lòng quá rồi. Bản cung dùng ai, tin ai là quyền của bản cung, hà cớ gì Thục Phi muội muội phải đem theo cả đao kiếm sáng loáng của cấm quân vào điện làm kinh động đến thai nhi của ta thế này?\"\n\n\"Tỷ tỷ thứ lỗi cho muội muội.\" Thục Phi khẽ mỉm cười, đôi mắt lá liễu liếc xéo về phía tôi đang đứng cúi đầu nghiêm trang ở góc điện: \"Bởi vì rạng sáng ngày hôm nay, thái giám phụ trách ngự dược phòng đã phát hiện ra trong kho cất giữ dược liệu quý của hoàng gia có kẻ lén lút cạy khóa đánh cắp nửa lạng xạ hương cực phẩm và năm đồng tiền phụ tử chế kịch độc. Kẻ trộm trong lúc trốn chạy đã để lại dấu vết bùn đất đỏ đặc trưng chỉ có ở luống hoa hậu viện cung Vĩnh Hòa. Nếu tỷ tỷ thật lòng trong sạch không che giấu kẻ gian, xin hãy để Ôn đại phu vào lục soát gian phòng của con a hoàn này.\"\n\nPhu nhân họ Liễu từ ngoài sân vội vã chạy xộc vào trong điện, vừa nghe thấy lời Thục Phi liền quỳ rạp xuống đất khóc lóc thảm thiết: \"Xin Thục Phi nương nương và Ôn đại nhân khai ân soi xét! Con bé Diệp Anh này từ nhỏ mẹ đẻ mất sớm, sống buông thả ngoài thảo nguyên, tính nết gian manh trộm cắp quen thói. Phủ Chu gia chúng tôi thật lòng không hề hay biết nó dám cả gan to mật lớn đánh cắp đồ của ngự dược phòng! Xin các ngài cứ việc bắt nó đi chém đầu răn đe, ngàn vạn lần đừng giáng tội xuống gia quyến họ Chu vô tội của chúng tôi!\"\n\nTôi nhìn người đàn bà mang danh mẹ kế ấy, trong lòng không hề gợn lên một chút xót xa hay đau đớn nào nữa. Suốt mười tám năm qua, bà ta chưa từng coi tôi là con người ruột thịt, mỗi khi gia đình gặp sóng gió tai ương đều đem tôi ra làm bia đỡ đạn hứng chịu mọi đòn roi. Nhưng hôm nay, tôi không còn là con bé gầy gò chỉ biết cắn răng nuốt nước mắt vào trong nơi căn nhà kho ẩm thấp năm nào nữa.\n\n\"Ôn chưởng viện,\" tôi bình thản bước ra giữa đại điện, giọng nói trong trẻo và đĩnh đạc vang vọng khắp bốn góc phòng: \"Ngài nói trong kho ngự dược bị kẻ gian cạy khóa trộm mất phụ tử chế và xạ hương đúng không?\"\n\nÔn Thuận Cảnh vuốt chòm râu bạc dài đến ngực, hừ lạnh một tiếng đầy khinh bỉ: \"Đúng vậy! Đó là hai vị thuốc cấm nghiêm ngặt trong cung cấm, chỉ cần nửa chỉ là có thể làm hại đến long thai của Quý phi và tính mạng của các bậc cung tần. Gian phòng ngủ của ngươi ở ngay sát vách luống hoa hậu viện, nếu ngươi thật sự trong sạch, cớ sao dưới đế giày vải của ngươi lại dính đầy đất đỏ ẩm ướt của vườn ngự dược?\"\n\nTôi khẽ mỉm cười nhẹ nhõm, cúi xuống nhìn đôi giày vải màu đen giản dị của mình: \"Đất đỏ ở vườn ngự dược Thái Y Viện được trộn cùng vụn vỏ cây thông và tro trấu để giữ ẩm cho rễ cây sâm. Đúng là đêm qua tôi có đến đó, nhưng không phải để trộm thuốc, mà là để kiểm chứng một nghi vấn lớn liên quan đến tính mạng của Quý phi.\"\n\nThục Phi lập tức chộp lấy cơ hội, cất giọng the the quát lớn đầy đắc thắng: \"Hoàng thiên có mắt, ngươi đã tự miệng thừa nhận hành vi lén lút rồi nhé! Cấm quân đâu, mau lôi ả tiện tỳ to gan này ra ngoài sân viện đánh chết bằng gậy cho ta!\"\n\n\"Chậm đã!\" Tiêu Quý phi đập mạnh bàn tay xuống chiếc bàn trà bằng gỗ mun, tiếng va đập chát chúa làm vỡ toang chiếc chén sứ men lam. \"Để nó nói hết câu! Bản cung ngồi ở đây xem thử ai dám tự tiện động thủ hành hình người trong cung Vĩnh Hòa này!\"\n\nTôi ngẩng cao đầu, ánh mắt sắc lẹm nhìn thẳng vào khuôn mặt đang hơi biến sắc của Ôn chưởng viện: \"Ôn đại phu, ngài là bậc danh y ba mươi năm phục vụ trong chốn hoàng cung, ngài có biết phụ tử chế khi tiếp xúc trực tiếp với da thịt người qua đường mồ hôi sẽ để lại phản ứng hóa học gì không?\"\n\nÔn Thuận Cảnh ngẩn người ra một thoáng, đôi mắt ông ta chớp liên tục, giọng nói bắt đầu ấp úng mất tự nhiên: \"Phụ tử chế... vốn là vị thuốc chí dương chí nhiệt, độc tính cực kỳ mãnh liệt, khi chế biến phải cẩn trọng...\"\n\n\"Phụ tử chế của hoàng gia được sao tẩm cùng gừng tươi già và nước tiểu đồng tử theo phương pháp bí truyền của triều đình, khi ngấm vào mồ hôi tay của con người sẽ tạo ra một mùi thơm hăng hắc như mùi rỉ sắt của kim loại, rửa bằng nước giếng lạnh hay nước hoa hồng ba ngày ba đêm cũng không thể nào tan hết được.\" Tôi vừa nói vừa giơ hai bàn tay trắng trẻo, thanh mảnh và sạch sẽ của mình lên trước mặt bàn dân thiên hạ: \"Hai bàn tay của tôi hoàn toàn khô ráo và sạch sẽ, không hề vương một chút mùi vị lạ. Nhưng ngài Ôn đại phu và Thục Phi nương nương có dám bảo người hầu cận thân tín nhất của mình xòe bàn tay ra cho mọi người ở đây cùng ngửi thử một lần không?\"\n\nÁnh mắt tôi ghim chặt không rời vào người cung nữ thân cận đang đứng khép nép run rẩy sau lưng Thục Phi, ả ta tên là Thúy Nga, người từng nhiều lần lén lút mang quà cáp đến cung Vĩnh Hòa thăm dò tin tức.\n\nNghe thấy lời phân tích dược tính rành rẽ của tôi, hai vai Thúy Nga run rẩy bần bật như phải bỏng, ả ta hoảng loạn vội vàng rụt hai tay vào sâu trong ống tay áo gấm thụng.\n\n\"Bắt lấy nó cho ta!\" Tiêu Quý phi lập tức quát lớn ra lệnh.\n\nThị vệ thân cận của Quý phi như chim ưng vồ mồi lao tới túm chặt lấy cổ tay Thúy Nga, kéo giật hai bàn tay của ả ra trước ánh sáng chói chang của ban ngày. Quả nhiên, trên mười đầu ngón tay của ả ta xuất hiện những vệt ố vàng nhạt hằn sâu dưới kẽ móng, một mùi hăng nồng nặc tanh tao bốc lên khiến những cung nữ đứng gần đều phải nhăn mặt bịt mũi tránh xa.\n\n\"Chưa dừng lại ở đó đâu,\" tôi bước tới gần chiếc tráp thuốc bằng da hươu mà Ôn chưởng viện mang theo, rút từ trong tay áo ra một chiếc đèn nến nhỏ đang cháy le lói: \"Thục Phi nương nương vu khống cho tôi ăn cắp xạ hương để hãm hại long thai của Quý phi. Nhưng loại xạ hương thượng hạng tiến cống từ Tây Vực năm nay đều được đóng dấu triện son đỏ của Lại Bộ và Hộ Bộ. Chiếc tráp thuốc của Ôn chưởng viện hôm nay mang đến đây viện cớ khám nghiệm bệnh tình, ngăn đáy thứ ba có một lớp lót bằng nhung đỏ dày bất thường, xin hỏi ngài cất giấu bảo vật gì bí mật ở bên dưới đó?\"\n\nSắc mặt Ôn Thuận Cảnh lúc này từ hồng hào kiêu hãnh chuyển sang tái mét như một xác chết trôi sông. Toàn thân ông ta nhũn ra, run rẩy quỳ sụp xuống đất van xin: \"Nương nương tha mạng... Lão thần... lão thần tuổi già lú lẫn, thật sự không hề biết trong tráp có thứ gì...\"\n\nThị vệ của Quý phi lập tức giật lấy chiếc tráp thuốc, dùng dao găm cạy tung lớp lót nhung đỏ lên. Dưới đáy tráp bí mật là một gói giấy dầu chứa đầy những hạt xạ hương màu nâu sẫm còn nguyên dấu triện son, kèm theo một lá thư viết tay bằng mực tím có đóng con dấu riêng của phủ bá tước Giang Nam!\n\nThục Phi lảo đảo lùi lại ba bước, hai chân mềm nhũn ngã ngồi phịch xuống chiếc ghế gụ, chiếc khăn tay thêu rơi tuột xuống sàn đất bẩn. Toàn bộ mưu kế gắp lửa bỏ tay người tinh vi, vừa muốn âm thầm trừ khử long thai của Tiêu Quý phi vừa muốn nhân cơ hội này đổ sạch tội lỗi lên đầu tôi và cả dòng họ Chu gia đã hoàn toàn bị lật tẩy trần trụi giữa thanh thiên bạch nhật!\n\n\"Mang toàn bộ tang vật và những kẻ này áp giải đến Cung Càn Thanh ngay lập tức!\" Tiêu Quý phi đứng phắt dậy, đôi mắt bừng bừng sát khí ngút trời: \"Bản cung muốn xem thử, trước mặt Hoàng thượng và văn võ bá quan, Thục Phi tỷ muội tốt của ta sẽ dùng những lời lẽ hoa mỹ nào để ngụy biện cho bức mật thư này!\""
    part3_full = "Dưới ánh nến lập lòe của đại điện Càn Thanh, khay thuốc giải độc và bức mật thư đóng dấu riêng của Thục phi được dâng thẳng lên trước mặt Hoàng thượng. Cung Càn Thanh đêm hôm ấy chìm trong một bầu không khí ngột ngạt và u ám đến mức nghẹt thở.\n\nHoàng thượng ngồi uy nghiêm trên ngai vàng rồng chạm khắc tinh xảo, long nhan đanh lại lạnh buốt như băng tuyết ngàn năm trên đỉnh núi cao. Dưới thềm son lộng lẫy, Thục Phi và Ôn Thuận Cảnh đang quỳ rạp trên mặt đất lạnh giá, toàn thân run rẩy như những chiếc lá rụng trước cơn bão tuyết đầu mùa đông.\n\nBên cạnh họ, toàn bộ tang vật vụ án gồm gói xạ hương Tây Vực còn nguyên dấu triện son, nắm bột trầm hương kịch độc trộn keo thông mật, và bức mật thư gửi từ phủ bá tước Giang Nam được bày la liệt trên chiếc mâm đồng lớn.\n\n\"Hoàng thượng bớt giận, thần thiếp thật sự bị kẻ gian hãm hại và gài bẫy oan uổng!\" Thục Phi dập đầu liên tục xuống nền gạch xanh bóng loáng, trán rớm ra những giọt máu tươi đỏ thắm: \"Bức thư đó chắc chắn là do có kẻ ngụy tạo con dấu gia tộc của phụ thân thần thiếp để vu oan giá họa! Thần thiếp từ trước đến nay một lòng ăn chay niệm Phật, đối đãi với Quý phi tỷ tỷ như người ruột thịt trong nhà, trời đất chứng giám sao thần thiếp có thể ra tay tàn độc đến mức đó được?\"\n\nHoàng thượng không thèm liếc nhìn bà ta lấy một cái, ánh mắt sắc lạnh của bậc đế vương chậm rãi dời sang phía tôi đang quỳ đoan trang ở phía dưới: \"Ngươi chính là đứa thứ nữ của Chu gia đã nhìn thấu độc chất trong lò xông trầm sao?\"\n\n\"Dạ bẩm Hoàng thượng, đúng là tiện nữ.\" Tôi quỳ gối ngay ngắn, sống lưng thẳng tắp như cây tùng giữa bão tuyết, giọng nói vang lên đĩnh đạc và rành rọt không chút run sợ: \"Tiện nữ từ nhỏ theo mẫu thân học y thuật dân gian ngoài thảo nguyên, biết rằng mỗi một loài cỏ cây thảo mộc trên thế gian này đều có linh tính, hương sắc và dấu vết riêng biệt của nó. Kẻ có dã tâm hại người có thể dùng muôn vàn lời lẽ dối trá để che mắt thiên hạ, nhưng dược tính và quy luật của đất trời thì vĩnh viễn không bao giờ biết nói dối.\"\n\n\"Ngươi bảo bức thư này chắc chắn không phải đồ ngụy tạo?\" Hoàng thượng gặng hỏi, giọng trầm đục đầy uy quyền.\n\n\"Muốn biết bức mật thư này có phải ngụy tạo hay không, chỉ cần một chén nước trà hoa quế tươi vừa mới hãm.\" Tôi bình tĩnh nâng niu dâng lên một chiếc chén sứ nhỏ đựng nước trà trong vắt không chút gợn đục: \"Loại mực tím dùng để viết bức mật thư này không phải là mực nho thông thường của kinh thành, mà là mực bí truyền được chiết xuất từ rễ cây Tử Thảo chỉ mọc ở vùng đầm lầy thuộc thái ấp của Giang Nam bá tước. Loại mực này khi tiếp xúc với tinh chất của trà hoa quế sẽ phát ra ánh lân quang màu xanh lục kỳ ảo trong bóng tối. Nếu là mực giả mạo ở kinh thành, nó sẽ lập tức tan biến thành những vệt cặn màu đen kịt.\"\n\nDưới sự cho phép nghiêm cẩn của Hoàng thượng, tổng quản thái giám Lý Ân đích thân cầm chiếc chén sứ, cẩn thận nhỏ một giọt nước trà hoa quế lên mép dưới của lá thư.\n\nNgay khi ngọn nến lớn trong đại điện vừa được hạ bớt độ sáng, giọt nước trà hoa quế vừa chạm vào mặt giấy liền lập tức phát ra một luồng sáng xanh biếc lấp lánh như ngọc lục bảo giữa màn đêm tăm tối, soi rõ từng nét chữ viết tay sắc sảo và con dấu gia tộc hình hoa sen của dòng họ Thục Phi!\n\nCả đại điện Cung Càn Thanh vang lên những tiếng xì xào kinh hãi tột độ của các bậc đại thần và cấm quân thị vệ.\n\nThục Phi như bị một bàn tay vô hình rút cạn toàn bộ sinh lực trong cơ thể, cả người bà ta đổ sụp xuống mặt đất lạnh ngắt, đôi mắt đờ đẫn vô hồn nhìn chằm chằm vào luồng sáng xanh lục ma quái ấy. Đến nước này, mọi lời ngụy biện thề thốt trơ trẽn đều trở nên vô nghĩa trước sự thật sắt đá và chuẩn xác của dược lý ngàn năm.\n\n\"Tiện nhân ác độc!\" Hoàng thượng đập mạnh long bào xuống mặt bàn rồng, tiếng gầm thét vang dội như sấm sét xé toạc màn đêm tĩnh mịch: \"Trẫm đối đãi với mẫu tộc ngươi không hề bạc bẽo, phong quan tiến tước, ngươi lại dám đem kịch độc vào thâm cung mưu hại long thai của Quý phi, lộng quyền lấn át kỷ cương của hoàng triều! Người đâu, lập tức tước bỏ phong hiệu Thục Phi, tước bỏ ngọc điệp, giáng làm thứ dân đày vào lãnh cung giam cầm trọn đời! Toàn bộ tôn thất chi tộc của bá tước Giang Nam lập tức bị niêm phong tài sản, bắt giam toàn bộ giao cho Đại Lý Tự điều tra nghiêm trị!\"\n\n\"Còn ngươi nữa, Ôn Thuận Cảnh,\" ánh mắt rực lửa của Hoàng thượng nhìn sang vị viện trưởng Thái Y Viện đang run lẩy bẩy như cầy sấy: \"Là quan đứng đầu y viện triều đình, nắm giữ sinh mệnh bao người mà lại tham lam tiền tài câu kết mưu hại hậu phi, lập tức cách chức toàn bộ, tịch thu gia sản, tống giam vào thiên lao chờ ngày xử trảm thị chúng!\"\n\nTiếng gào khóc thảm thiết, van xin trong tuyệt vọng của Thục Phi và Ôn chưởng viện vang vọng khắp hành lang sâu hun hút của Cung Càn Thanh rồi lịm dần khi họ bị thị vệ cấm quân kéo lê ra ngoài cổng thành.\n\nĐại điện rộng lớn trở lại vẻ tĩnh mịch uy nghiêm vốn có.\n\nHoàng thượng nhìn xuống tôi, ánh mắt lộ rõ vẻ thán phục và trân trọng hiếm thấy ở một bậc chí tôn: \"Ngươi tuổi còn trẻ nhưng tài trí hơn người, có công lớn cứu vãn long tự của hoàng gia, lại phá được kỳ án thâm cung mười năm chưa ai giải nổi. Chu gia của ngươi sinh được một người con gái tài đức vẹn toàn thế này, trẫm nên ban thưởng cho ngươi thứ gì xứng đáng đây? Ban cho ngươi làm tần phi trong cung hưởng vinh hoa phú quý, hay phong cho cha ngươi lên làm Thượng thư Lục Bộ?\"\n\nLúc này, cha tôi và bà mẹ kế họ Liễu đang đứng khép nép ở góc điện, hai mắt sáng rực lên vì sự tham lam tột độ. Cha tôi thậm chí còn nôn nóng nháy mắt liên tục ra hiệu cho tôi phải nhanh chóng quỳ xuống cầu xin chức tước bổng lộc cho ông ta.\n\nNhưng tôi khẽ mỉm cười nhẹ nhõm, quỳ sụp xuống dập đầu ba lạy thật sâu trước ngai vàng rực rỡ: \"Tâu Hoàng thượng anh minh, tiện nữ không mong cầu vinh hoa phú quý hư ảo, cũng không hề thiết tha danh phận tần phi chốn hậu cung sâu thẳm. Tiện nữ chỉ có hai tâm nguyện khẩn thiết cả đời xin Hoàng thượng từ bi chuẩn tấu.\"\n\n\"Ngươi cứ nói thẳng, trẫm ban cho ngươi.\" Hoàng thượng khẽ nhướng mày tò mò.\n\n\"Tâm nguyện thứ nhất: Xin Hoàng thượng hạ chiếu thư cho phép mẫu thân đã khuất của tiện nữ được khôi phục danh phận chính thê, đưa bài vị vào từ đường tổ tiên hương khói đàng hoàng, và cho phép xóa tên tiện nữ ra khỏi gia phả họ Chu. Từ nay về sau, sống chết sang hèn của tiện nữ không còn liên can gì đến Chu gia nữa!\"\n\nLời nói đanh thép vừa dứt, cha tôi và phu nhân họ Liễu đứng phía sau chết sững như bị sét đánh ngang tai. Mặt họ xám ngoét không còn hột máu, run rẩy ú ớ không thốt nên lời trước sự đoạn tuyệt tuyệt đối của tôi.\n\n\"Tâm nguyện thứ hai,\" tôi ngẩng cao đầu, ánh mắt sáng ngời kiên định như vì sao giữa trời đêm: \"Xin Hoàng thượng cho phép tiện nữ được nhập ngạch Thái Y Viện với thân phận Nữ Ngự Y Đệ Nhất Viện, mở rộng y quán cứu chữa miễn phí cho những bần nông nghèo khổ khắp kinh kỳ, dùng y thuật chân chính của mẫu thân để cứu vớt người đời chứ tuyệt đối không làm quân cờ tranh đoạt quyền lực dơ bẩn!\"\n\nHoàng thượng im lặng nhìn tôi suốt một hồi lâu giữa đại điện trang nghiêm. Trong đôi mắt thâm sâu của bậc đế vương ánh lên sự kinh ngạc tột độ xen lẫn niềm kính trọng sâu sắc đối với một người con gái có khí phách ngút ngàn.\n\nMột nén nhang sau, một tràng cười sảng khoái và vang dội của Hoàng thượng vang khắp đại điện Cung Càn Thanh:\n\n\"Hay cho một câu 'dùng y thuật cứu vớt người đời chứ tuyệt đối không làm quân cờ tranh quyền'! Chu Diệp Anh, trẫm chuẩn tấu toàn bộ tâm nguyện chính trực của ngươi! Ngay ngày mai, phong ngươi làm Nữ Ngự Y Đệ Nhất Viện, ban kim bài miễn tử mang bên mình, địa vị và quyền hạn ngang hàng với viện trưởng Thái Y Viện!\"\n\nKhi tôi bước chân ra khỏi ngưỡng cửa Cung Càn Thanh, bầu trời phương đông xa xăm đã bắt đầu hừng đông rạng sáng.\n\nMột làn gió sớm trong lành của mùa xuân thổi qua tà áo giản dị của tôi, cuốn đi toàn bộ mùi trầm hương tanh nồng và những âm mưu tăm tối của chốn thâm cung sâu thẳm. Phía sau lưng tôi, bóng dáng cha tôi và người mẹ kế độc ác đang lầm lũi cúi đầu rời đi trong sự nhục nhã ê chề và tiếc nuối tột cùng. Còn phía trước tôi là con đường thênh thang ngập tràn ánh nắng ban mai rực rỡ, nơi tôi sẽ tự tay cầm lấy ngọn bút và cây kim châm cứu, viết nên trang sử huy hoàng của chính cuộc đời mình."
